sys_script_include.script:
var GroupRoleValidator = Class.create();
GroupRoleValidator.prototype = {

    hasRoleViaGroup: function(userSysId, roleName) {

        // 1. Busca o sys_id da role pelo nome
        var role = new GlideRecord('sys_user_role');
        role.addQuery('name', roleName);
        role.query();
        if (!role.next()) return false;
        var roleSysId = role.getValue('sys_id');

        // 2. Busca grupos que têm essa role
        var groupRole = new GlideRecord('sys_group_has_role');
        groupRole.addQuery('role', roleSysId);
        groupRole.query();

        var groupIds = [];
        while (groupRole.next()) {
            groupIds.push(groupRole.getValue('group'));
        }
        if (groupIds.length === 0) return false;

        // 3. Verifica se o usuário está em algum desses grupos
        var gm = new GlideRecord('sys_user_grmember');
        gm.addQuery('user', userSysId);
        gm.addQuery('group', 'IN', groupIds.join(','));
        gm.query();

        return gm.hasNext();
    },

    type: 'GroupRoleValidator'
};
